import argparse
import json
import sqlite3
import subprocess
import sys
import requests

def parse_args():
    parser = argparse.ArgumentParser(description='Process pending jobs from database.')
    parser.add_argument('config', type=str, help='Path to JSON configuration file')
    parser.add_argument('db', type=str, help='Path to SQLite database file')
    return parser.parse_args()

def load_config(config_path):
    with open(config_path, 'r') as f:
        return json.load(f)

def get_db_connection(db_path):
    return sqlite3.connect(db_path)

def process_job(job_id, config):
    conn = get_db_connection(config['db'])
    cursor = conn.cursor()

    table = config['table']
    id_column = config['id_column']
    command_column = config['command_column']
    endpoint_column = config['endpoint_column']
    status_column = config['status_column']

    cursor.execute(f"SELECT {command_column}, {endpoint_column}, {status_column} FROM {table} WHERE {id_column} = ?", (job_id,))
    row = cursor.fetchone()

    if not row:
        return

    command, endpoint, status = row
    if status != 'pending':
        return

    try:
        response = requests.post(endpoint, json={"job_id": job_id})
        if response.status_code == 200:
            try:
                result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
                cursor.execute(f"UPDATE {table} SET {status_column} = 'done' WHERE {id_column} = ?", (job_id,))
                print(result.stdout, end='')
                print(result.stderr, end='')
            except subprocess.CalledProcessError as e:
                cursor.execute(f"UPDATE {table} SET {status_column} = 'failed' WHERE {id_column} = ?", (job_id,))
                print(f"Command failed with exit code {e.returncode}: {e.stderr}", file=sys.stderr)
        else:
            print(f"skip {job_id}")
    finally:
        conn.commit()
        conn.close()

def main():
    args = parse_args()
    config = load_config(args.config)

    for line in sys.stdin:
        line = line.strip()
        if line:
            process_job(line, config)

    print(f"processed {len(sys.stdin)}")

if __name__ == "__main__":
    main()
